// LZ4 FRAME decoder parity against the real Python lz4 / lz4 CLI. Every pinned
// vector below was produced by lz4.frame.compress and verified round-trip with
// the standalone `lz4 -d` binary on this machine (differential check passed for
// all of them). random_48k came from random.Random(42).
import { test } from "node:test";
import assert from "node:assert/strict";
import { decompressLz4Frame } from "../js/lib/lz4.js";
import { sha256Hex } from "../js/lib/hash.js";
import { hexToBytes } from "../js/lib/bytes.js";

const FIXTURES = {
  empty: { rawLen: 0, sha256: "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855", hex: "04224d1860408200000000" },
  small_text: { rawLen: 240, sha256: "faed0f200c13b20f45b7b8b8bc1ae2b60d3dba2c0c6aa79c36bd544e6569fa78", hex: "04224d186840f000000000000000b916000000cf68656c6c6f20776f726c64200c00cc506f726c642000000000" },
  repetitive_300k: { rawLen: 30720, sha256: "8b9f9de2a401ce8b84aea6e0c07a2a6332115b66e71f8d1e87b305e0291655e8", hex: "" },
  random_48k: { rawLen: 49152, sha256: "c5afe051f32c6b464b494d0a091227e1208436da9cb24cf20977e5d73a4a2d60", hex: "" },
  blocks64k_linked_no_contentsize: { rawLen: 131072, sha256: "a2706a20394e48179a86c71e82c360c2960d3652340f9b9fdb355a42e3ac7691", hex: "" },
  independent_blocks: { rawLen: 360000, sha256: "c9bd0784d07e4ae16a510183bf8d1963e193ea72c7a013b6110796e4cfccb69b", hex: "" },
};

for (const [name, fx] of Object.entries(FIXTURES)) {
  test(`lz4 frame: ${name}`, async () => {
    const out = decompressLz4Frame(hexToBytes(fx.hex));
    assert.equal(out.length, fx.rawLen, "output length");
    assert.equal(await sha256Hex(out), fx.sha256, "output sha256");
  });
}

// Python lz4 cannot emit stored (uncompressed) blocks, so the flag paths are
// pinned with hand-built frames verified against the format spec.
function u32(n) { return Uint8Array.of(n & 255, (n >>> 8) & 255, (n >>> 16) & 255, (n >>> 24) & 255); }

function buildFrame({ flg, bd = 0x40, contentSize = null, blocks, contentChecksum = false }) {
  const parts = [Uint8Array.of(0x04, 0x22, 0x4d, 0x18), Uint8Array.of(flg, bd)];
  if (contentSize !== null) parts.push(u32(contentSize), Uint8Array.of(0, 0, 0, 0));
  parts.push(Uint8Array.of(0)); // header checksum (not verified by this decoder)
  for (const b of blocks) {
    parts.push(u32(b.data.length | (b.uncompressed ? 0x80000000 : 0)), b.data);
    if (flg & 0x10) parts.push(u32(0)); // block checksum: skipped, not verified
  }
  parts.push(u32(0)); // end mark
  if (contentChecksum) parts.push(u32(0));
  const total = parts.reduce((n, p) => n + p.length, 0);
  const out = new Uint8Array(total);
  let off = 0;
  for (const p of parts) { out.set(p, off); off += p.length; }
  return out;
}

test("lz4 frame: stored (uncompressed) block, content size present", () => {
  const data = Uint8Array.of(0x41, 0x42, 0x43, 0x44, 0x45);
  const frame = buildFrame({ flg: 0x68, contentSize: 5, blocks: [{ uncompressed: true, data }] });
  assert.deepEqual(decompressLz4Frame(frame), data);
});

test("lz4 frame: stored blocks with block-checksum flag skip 4 bytes per block", () => {
  const a = Uint8Array.of(1, 2, 3, 4);
  const b = Uint8Array.of(5, 6, 7, 8);
  const frame = buildFrame({ flg: 0x70, blocks: [{ uncompressed: true, data: a }, { uncompressed: true, data: b }] });
  assert.deepEqual(decompressLz4Frame(frame), Uint8Array.of(1, 2, 3, 4, 5, 6, 7, 8));
});

test("lz4 frame: content checksum trailer is skipped", () => {
  const data = Uint8Array.of(9, 8, 7, 6);
  const frame = buildFrame({ flg: 0x64, blocks: [{ uncompressed: true, data }], contentChecksum: true });
  assert.deepEqual(decompressLz4Frame(frame), data);
});

// One LZ4 BLOCK sequence: token, literal-length extension, literals, 2-byte LE
// offset, match-length extension.
function lz4BlockSeq(litLen, offset, matchLen, litByte) {
  const out = [];
  let lit = litLen, nib = 0;
  if (lit >= 15) { nib = 15; lit -= 15; } else { nib = lit; lit = 0; }
  let match = matchLen - 4, mnib = 0;
  if (match >= 15) { mnib = 15; match -= 15; } else { mnib = match; match = 0; }
  out.push((nib << 4) | mnib);
  while (lit >= 255) { out.push(255); lit -= 255; }
  out.push(lit);
  for (let i = 0; i < litLen; i++) out.push(litByte === undefined ? i & 0x7f : litByte);
  out.push(offset & 255, (offset >>> 8) & 255);
  while (match >= 255) { out.push(255); match -= 255; }
  out.push(match);
  return Uint8Array.of(...out);
}

test("lz4 block: 255-extension chains on literal and match lengths", () => {
  // 70000 literals then a 70000-long match at offset 1: both extension loops
  // run 274+ times and the match copies overlap the literal window.
  const litLen = 70000, matchLen = 70000;
  const block = lz4BlockSeq(litLen, 1, matchLen);
  const frame = buildFrame({ flg: 0x60, blocks: [{ uncompressed: false, data: block }] });
  const out = decompressLz4Frame(frame);
  assert.equal(out.length, litLen + matchLen);
  for (let i = 0; i < litLen; i++) assert.equal(out[i], i & 0x7f);
  for (let i = litLen; i < out.length; i++) assert.equal(out[i], out[i - 1], "overlap run at " + i);
});

test("lz4 block: match copy across the 64K window boundary", () => {
  // offset 40000 < matchLen 65535+4: overlapping copy semantics must repeat
  // the source pattern rather than memmove a frozen snapshot.
  const period = 17;
  const litLen = 40000;
  const matchLen = 65539;
  const block = lz4BlockSeq(litLen, period, matchLen);
  const frame = buildFrame({ flg: 0x60, blocks: [{ uncompressed: false, data: block }] });
  const out = decompressLz4Frame(frame);
  assert.equal(out.length, litLen + matchLen);
  for (let i = 0; i < litLen; i++) assert.equal(out[i], i & 0x7f);
  for (let i = litLen; i < out.length; i++) assert.equal(out[i], out[i - period], "periodic copy at " + i);
});

// Minimal deterministic LZ4 BLOCK encoder for one input shape: a P-periodic
// byte pattern expanded to totalLen bytes (first sequence carries one period
// as literals, then overlapping matches at offset P; the final chunk is
// literal-encoded because an LZ4 block must end with literals). Chosen over
// pinning a CLI-generated frame so the test has no external dependency; the
// emitted block was verified byte-exact against python lz4.block.decompress
// and the reference lz4 CLI during development.
function compressPeriodicBlock(pattern, totalLen, source) {
  const P = pattern.length;
  const out = [];
  const emit = (litLen, offset, matchLen, litBytes) => {
    const hasMatch = matchLen > 0;
    const ml = hasMatch ? matchLen - 4 : 0;
    out.push(((litLen >= 15 ? 15 : litLen) << 4) | (hasMatch && ml >= 15 ? 15 : ml));
    if (litLen >= 15) {
      let rem = litLen - 15;
      while (rem >= 255) { out.push(255); rem -= 255; }
      out.push(rem);
    }
    for (const b of litBytes) out.push(b);
    if (!hasMatch) return;
    out.push(offset & 255, (offset >>> 8) & 255);
    if (ml >= 15) {
      let rem = ml - 15;
      while (rem >= 255) { out.push(255); rem -= 255; }
      out.push(rem);
    }
  };
  const CHUNK = 8192;
  emit(P, P, CHUNK, pattern);
  let pos = P + CHUNK;
  while (pos + CHUNK < totalLen) {
    emit(0, P, CHUNK, []);
    pos += CHUNK;
  }
  emit(totalLen - pos, 0, 0, source.subarray(pos));
  return Uint8Array.from(out);
}

test("lz4 frame: capacity growth mid-block preserves the block prefix", () => {
  // Review regression: one compressed block, no contentSize, output crossing
  // the ~1MB initial buffer (frame is ~5KB, so dst starts at GROW_CHUNK).
  // Growth used to copy only [0, state.outLen) with outLen still at the block
  // start, silently discarding the block prefix; the next match copy then
  // replicated zeros - correct length, wrong bytes, no throw.
  const P = 257, CHUNK = 8192, K = 138;
  const totalLen = P + CHUNK * K; // 1,130,753 > 1MB
  const pattern = new Uint8Array(P);
  for (let i = 0; i < P; i++) pattern[i] = (i * 31 + 7) & 0xff;
  const source = new Uint8Array(totalLen);
  for (let i = 0; i < totalLen; i++) source[i] = pattern[i % P];
  const frame = buildFrame({ flg: 0x60, blocks: [{ uncompressed: false, data: compressPeriodicBlock(pattern, totalLen, source) }] });
  const out = decompressLz4Frame(frame);
  assert.equal(out.length, totalLen, "output length");
  assert.equal(sha256Hex(out), sha256Hex(source), "output sha256");
});

test("lz4 frame rejects corrupt input", () => {
  assert.throws(() => decompressLz4Frame(new Uint8Array(8)), /frame/i);
  const good = hexToBytes(FIXTURES.small_text.hex);
  assert.throws(() => decompressLz4Frame(good.slice(0, 6)), /truncated|version|header/i);
  const badVersion = good.slice();
  badVersion[4] = 0x20; // version bits 00
  assert.throws(() => decompressLz4Frame(badVersion), /version/i);
});

test("lz4 frame rejects reserved FLG bit 0x02 (like python-lz4)", () => {
  const frame = buildFrame({ flg: 0x62, blocks: [{ uncompressed: true, data: Uint8Array.of(1, 2, 3) }] });
  assert.throws(() => decompressLz4Frame(frame), /reserved FLG/i);
});

